function l(e,r,n,o=[]){let a=0,s=0,i=0,u=0;for(let t=0;t<e.length;t++)a+=e[t].questions.length;for(let t=0;t<r.length;t++)for(const c of r[t].data)s+=1;for(let t=0;t<n.length;t++)for(const c of n[t].data)i+=c.questions.length;for(let t=0;t<o.length;t++)u+=o[t].questions.length;return{part1:a,part2:s,part3:i,cauBanThem:u,total:a+s+i+u}}function p(e){const r=JSON.parse(e),n=r["PART 1"]??[],o=r["PART 2"]??[],a=r["PART 3"]??[],s=r["Câu bạn thêm"]??[];return l(n,o,a,s)}function f(e){const r=new Date().toLocaleString("en-US",{timeZone:"Asia/Ho_Chi_Minh"});return new Date(e).getTime()<new Date(r).getTime()}function h(e){return e.flatMap(n=>n.questions.map(o=>({topic:n.topic,question:o})))}function S(e){return e.flatMap(n=>n.data.flatMap(o=>o.questions.map(a=>({topic:n.topic,question:a}))))}function g(e){return e.flatMap(n=>n.data.map(o=>({topic:n.topic,question:o.title})))}export{g as a,S as b,p as c,l as d,h as g,f as i};
